-- 0019. Публичный сайт SMM KADR по коммерческому предложению 2026: блоки «slide» в CMS, журнал правок, замена изображений.
-- Прежние блоки не удаляются — скрываются и уходят в конец списка CMS.

-- ───────────── CMS: блоки-слайды презентации и журнал изменений ─────────────
alter table public.site_blocks drop constraint if exists site_blocks_type_check;
alter table public.site_blocks add constraint site_blocks_type_check
  check (type in ('hero','benefits','services','tariffs','cases','team','faq','contacts','cta','slide'));

create or replace function public.site_blocks_audit()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null and (new.draft is distinct from old.draft or new.visible is distinct from old.visible or new.sort is distinct from old.sort) then
    perform public.audit('site.block_draft', 'site_block', new.key,
      jsonb_build_object('visible', new.visible, 'sort', new.sort, 'title', coalesce(new.draft->>'rubric', new.draft->>'title')));
  end if;
  return new;
end $$;
drop trigger if exists site_blocks_audit_trg on public.site_blocks;
create trigger site_blocks_audit_trg after update on public.site_blocks for each row execute function public.site_blocks_audit();

create or replace function public.site_settings_audit()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    perform public.audit('site.settings', 'site', 'settings', to_jsonb(new) - 'updated_at');
  end if;
  return new;
end $$;
drop trigger if exists site_settings_audit_trg on public.site_settings;
create trigger site_settings_audit_trg after update on public.site_settings for each row execute function public.site_settings_audit();
revoke execute on function public.site_blocks_audit() from public, anon, authenticated;
revoke execute on function public.site_settings_audit() from public, anon, authenticated;

-- Загрузка/замена изображений сайта владельцем CMS (чтение bucket site — публичное, запись уже ограничена cms.manage)
drop policy if exists site_update on storage.objects;
create policy site_update on storage.objects for update to authenticated
  using (bucket_id = 'site' and public.has_perm('cms.manage')) with check (bucket_id = 'site' and public.has_perm('cms.manage'));

