-- прежние блоки сайта не удаляются: скрыты и перенесены в конец списка CMS
update public.site_blocks set visible = false, sort = sort + 900 where type <> 'slide' and sort < 900;
update public.site_settings set
  instagram = coalesce(instagram, 'https://instagram.com/smm_kadr'),
  whatsapp = coalesce(whatsapp, '+996 503 030 018')
 where id = 1;
update public.site_settings set
  seo_title = 'SMM KADR — маркетинг, который продаёт | Бишкек',
  seo_description = 'Контент, таргет и команда на аутсорсе: 6 специалистов, тарифы от 10 500 сом, работа по договору, ежемесячный отчёт и акт.'
 where id = 1 and seo_title = 'SMM KADR — продвижение, продакшн и таргет в Бишкеке';
insert into public.site_versions(snapshot, note)
select jsonb_agg(to_jsonb(b) order by b.sort), 'SMM KADR 2026: контент коммерческого предложения' from public.site_blocks b;
